-- 771_vetcomparison_correct_the_three_register_findings.sql
--
-- OWNER INSTRUCTION 2026-09-04: "please fix the vetcomparison copy". Repairs the three live errors
-- that the evidence-register pass RECORDED but deliberately did not repair (migration 759, four
-- `corrects_site_citation` entries). Nine `content_rewrite` items, one per affected page.
--
-- ─── THE THREE ERRORS, AND WHICH PAGES CARRY EACH `[MEASURED 2026-09-04 at the served bytes]` ──
--
--   E1  "final report in November 2024"        -> 24 March 2026            2 pages
--   E2  £21 / £12.50 stated as SETTLED         -> proposed in a draft      7 pages
--   E3  "36 service categories"                -> 36 services, 5 categories 8 pages
--
-- Nine distinct pages. E2 keeps both figures — what changes is that they are PROPOSED, not in force
-- — and uses the vetcomparison lane's own recommended wording verbatim.
--
-- ─── THE RECIPE, WHICH WAS BOUGHT WITH A REGRESSION ──────────────────────────────────────────
--
-- Every item sets `spec.mode='edit_live'`. Migration 739 (loancash, 2026-09-03) left it unset, so
-- page-build-handler REGENERATED each section instead of editing it: three pages were wholly
-- rewritten and lost their compliance disclaimer while retaining 84-88% of their BYTES. A length
-- check cannot see that; only a sentence-identity diff can.
--
-- Every item is `approval_mode='manual'`, so nothing dispatches until a human releases it
-- (`load_work_item_actions.go:802`). ⚠ AND THE 48-HOUR REAPER THEN FLIPS AN UNRELEASED ITEM TO
-- `unresolved`, WHICH READS AS PROCESSED. Release with
-- `UPDATE site_work_items SET status='approved' WHERE created_by='bugfix_414 register-programme lane (migration 771)' AND affected_url='<one page>'`
-- — ONE PAGE FIRST as a canary, verified at the bytes, before the other eight.
--
-- ⚠ THE ACCEPTANCE TEST DELIBERATELY DOES NOT SAY "NOTHING REWORDED". A correction necessarily
-- rewords the sentence it corrects. The measure is ORPHANED sentences — a removed sentence with no
-- close survivor — which must be 0. On the loancash restoration 5 sentences were "removed" at
-- 0.89-0.98 similarity with 0 orphaned, and the stricter test would have failed a correct repair.
--
-- ⚠ /guides/animal-health-certificates/ IS DELIBERATELY EXCLUDED and guard 4 enforces it. Its
-- article body is a hand-attested literal block (vetcomparison lane, 2026-08-27) that REPLACED three
-- model-memory falsehoods; a regeneration there would reintroduce them. Measured 2026-09-04: it
-- carries 0 instances of all three errors, so it needs no repair. The site's own lane was consulted
-- before filing and confirmed nothing is mid-flight on any of these pages.
--
-- Rollback: 771_..._ROLLBACK.sql

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM sites WHERE id = '72b9e3a6-872f-4528-a6d6-7f205ea60f4d' AND domain = 'vetcomparison.uk') THEN
    RAISE EXCEPTION '771 ABORT: site_id does not resolve to vetcomparison.uk';
  END IF;
END $$;

-- Guard 2: refuse if any of these repairs is already open (another session, or a re-run).
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM site_work_items
   WHERE site_id = '72b9e3a6-872f-4528-a6d6-7f205ea60f4d' AND item_key LIKE 'vetcomparison_fix_%'
     AND status NOT IN ('complete','verified','rejected','wont_fix','failed','unresolved','cancelled');
  IF n IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION '771 ABORT: % repair item(s) already open', coalesce(n::text,'NULL');
  END IF;
END $$;

-- Guard 3: the edit_live literal must be on page-build-handler's OWN live config, or every item
-- below is a silent full regeneration rather than an edit.
DO $$
DECLARE cfg text;
BEGIN
  SELECT default_config::text INTO cfg FROM agent_definitions
   WHERE type = 'page-build-handler' AND is_active
     AND COALESCE(is_snapshot,false) = false AND deleted_at IS NULL LIMIT 1;
  IF cfg IS NULL THEN
    RAISE EXCEPTION '771 ABORT: no live page-build-handler definition';
  END IF;
  IF cfg NOT LIKE '%load_current_section_content%' OR cfg NOT LIKE '%edit_live%' THEN
    RAISE EXCEPTION '771 ABORT: page-build-handler lacks load_current_section_content or the edit_live literal - the items would REGENERATE, not edit';
  END IF;
END $$;

